INSERT INTO _teaser_card_plan (site_id, column_name, old_value, new_value, change_key, reason, premise, evidence) VALUES
    ('09895c88-e3d8-4ad2-b23e-eef85097ab6e'::uuid, 'card_description', 'The smallest of Cheshire''s seven Iron Age hill forts, and the furthest north — in a county where hill forts are rare. A scheduled monument marking the frontier of Iron Age territory.', 'Higher ground closes in on most sides of Bradley Hill Fort, set on the steep banks of a River Weaver tributary: the smallest hill fort in Cheshire, still not investigated archaeologically.', 'teaser-card-s001:09895c88-e3d8-4ad2-b23e-eef85097ab6e:card_description', 'teaser-card-s001 (teaser-card): teaser card, 188 characters, checked PASS, web-verified VERIFIED', 'db5eb68827abf758b591ffd3a6ab300f5adfa46372bc3f7791ef00c446596b2d|0575243d071f21d358d08903f3440566d1adc2e329b1d65ef6df578b7325ac6d|0575243d071f21d358d08903f3440566d1adc2e329b1d65ef6df578b7325ac6d', '[{"source": "lane WB run wb-pilot-2026-09-26c: writer teaser-write-001", "url": "output/remediation/teaser/runs/wb-pilot-2026-09-26c/OUTCOMES.jsonl", "quote": "Higher ground closes in on most sides of Bradley Hill Fort, set on the steep banks of a River Weaver tributary: the smallest hill fort in Cheshire, still not investigated archaeologically."}, {"source": "lane WB run wb-pilot-2026-09-26c: checker teaser-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-pilot-2026-09-26c/OUTCOMES.jsonl", "quote": "Bradley Hill Fort is surrounded on most sides by higher ground [S3]; it is a hill fort in Cheshire [S1, S2]; it is set on the steep banks of a stream [S4]; that stream is a tributary of the River Weaver [S4]; it is the smallest hill fort in Cheshire [S5]; the site has not been investigated archaeologically [S7]"}, {"source": "lane WB run wb-pilot-2026-09-26c: verifier teaser-verify-001 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-pilot-2026-09-26c/OUTCOMES.jsonl", "quote": "Bradley Hill Fort is a hill fort in Cheshire, England [SUPPORTED: https://en.wikipedia.org/wiki/Bradley_hill_fort]; Higher ground surrounds the fort on most sides [SUPPORTED: https://en.wikipedia.org/wiki/Bradley_hill_fort]; A tributary of the River Weaver runs past the fort [SUPPORTED: https://en.wikipedia.org/wiki/Bradley_hill_fort]; The fort is set on the steep banks of that stream [SUPPORTED: https://en.wikipedia.org/wiki/Bradley_hill_fort]; It is the smallest hill fort in Cheshire [SUPPORTED: https://en.wikipedia.org/wiki/Bradley_hill_fort]; It has still not been investigated archaeologically [SUPPORTED: https://en.wikipedia.org/wiki/Bradley_hill_fort]"}]'::jsonb),
    ('0bb4315b-c214-4c45-8417-e34e12b71ace'::uuid, 'card_description', 'On chalky downland near Compton, this 5.7-hectare univallate hillfort shows signs of seasonal occupation. Grain storage pits and slag pits are the main archaeological traces found inside.', 'Up on the chalky downs of West Berkshire, on Cow Down between Compton and Hampstead Norreys, lies Perborough Castle: an Iron Age univallate hillfort covering approximately 14 acres.', 'teaser-card-s001:0bb4315b-c214-4c45-8417-e34e12b71ace:card_description', 'teaser-card-s001 (teaser-card): teaser card, 181 characters, checked PASS, web-verified VERIFIED', '93288080bf411662c79070ff8d4f82613e0ac3722b83c35abc60995090ff271c|61e5b9071d11567f843383b5f0d89ef42d513918347eac22aba103878b3dde85|61e5b9071d11567f843383b5f0d89ef42d513918347eac22aba103878b3dde85', '[{"source": "lane WB run wb-pilot-2026-09-26c: writer teaser-write-001", "url": "output/remediation/teaser/runs/wb-pilot-2026-09-26c/OUTCOMES.jsonl", "quote": "Up on the chalky downs of West Berkshire, on Cow Down between Compton and Hampstead Norreys, lies Perborough Castle: an Iron Age univallate hillfort covering approximately 14 acres."}, {"source": "lane WB run wb-pilot-2026-09-26c: checker teaser-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-pilot-2026-09-26c/OUTCOMES.jsonl", "quote": "Perborough Castle lies up on the chalky downs of West Berkshire [S2, S4]; it lies on Cow Down [S3]; it lies between Compton and Hampstead Norreys [S3]; it is an Iron Age hillfort [S1]; the hillfort is univallate [S1]; it covers approximately 14 acres [S2]"}, {"source": "lane WB run wb-pilot-2026-09-26c: verifier teaser-verify-001 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-pilot-2026-09-26c/OUTCOMES.jsonl", "quote": "Perborough Castle is a hillfort in West Berkshire, England (at Compton) [SUPPORTED: https://en.wikipedia.org/wiki/Perborough_Castle]; It dates from the Iron Age [SUPPORTED: https://en.wikipedia.org/wiki/Perborough_Castle]; It is univallate (a single rampart) [SUPPORTED: https://en.wikipedia.org/wiki/Perborough_Castle]; It lies up on the chalky downs of West Berkshire [SUPPORTED: https://en.wikipedia.org/wiki/Perborough_Castle]; It lies on Cow Down [SUPPORTED: https://en.wikipedia.org/wiki/Perborough_Castle]; It lies between Compton and Hampstead Norreys [SUPPORTED: https://en.wikipedia.org/wiki/Perborough_Castle]; It covers approximately 14 acres [SUPPORTED: https://en.wikipedia.org/wiki/Perborough_Castle]"}]'::jsonb),
    ('0d70773f-7235-4afe-bfef-75ec938701b3'::uuid, 'card_description', 'A Romano-Celtic temple active from around 69 AD to the late 4th century. Excavations revealed ritual deposits of bird skeletons paired with coins.', 'Above Bowleaze Cove, Jordan Hill Roman Temple is a Romano-Celtic ruin with a cemetery of cremations and inhumations and a precinct that held deposits of animal bones, ceramics and coins.', 'teaser-card-s001:0d70773f-7235-4afe-bfef-75ec938701b3:card_description', 'teaser-card-s001 (teaser-card): teaser card, 186 characters, checked PASS, web-verified VERIFIED', '8ece808127fb1da25f9abdcb023ba8c16d87cb535ae0048a64441c9850354e6f|0e0ae6a81fd4bc937fa8b52e57a3c8e73057aad6140d5dc77b40ff7e9f440e01|0e0ae6a81fd4bc937fa8b52e57a3c8e73057aad6140d5dc77b40ff7e9f440e01', '[{"source": "lane WB run wb-pilot-2026-09-26c: writer teaser-write-001", "url": "output/remediation/teaser/runs/wb-pilot-2026-09-26c/OUTCOMES.jsonl", "quote": "Above Bowleaze Cove, Jordan Hill Roman Temple is a Romano-Celtic ruin with a cemetery of cremations and inhumations and a precinct that held deposits of animal bones, ceramics and coins."}, {"source": "lane WB run wb-pilot-2026-09-26c: checker teaser-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-pilot-2026-09-26c/OUTCOMES.jsonl", "quote": "Jordan Hill Roman Temple is above Bowleaze Cove [S1]; it is a Romano-Celtic ruin [S1]; the site has a cemetery [S5]; the cemetery contains cremations and inhumations [S5]; it has a precinct [S4]; the precinct held deposits of animal bones, ceramics and coins [S4]"}, {"source": "lane WB run wb-pilot-2026-09-26c: verifier teaser-verify-001 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-pilot-2026-09-26c/OUTCOMES.jsonl", "quote": "Jordan Hill Roman Temple is a Romano-Celtic temple above Bowleaze Cove (Dorset, England) [SUPPORTED: https://en.wikipedia.org/wiki/Jordan_Hill_Roman_Temple]; The site is a ruin [SUPPORTED: https://en.wikipedia.org/wiki/Jordan_Hill_Roman_Temple]; The site includes a cemetery [SUPPORTED: https://en.wikipedia.org/wiki/Jordan_Hill_Roman_Temple]; The cemetery contains cremations [SUPPORTED: https://en.wikipedia.org/wiki/Jordan_Hill_Roman_Temple]; The cemetery contains inhumations [SUPPORTED: https://en.wikipedia.org/wiki/Jordan_Hill_Roman_Temple]; The temple stood within a precinct [SUPPORTED: https://en.wikipedia.org/wiki/Jordan_Hill_Roman_Temple]; The precinct held deposits of animal bones [SUPPORTED: https://www.english-heritage.org.uk/visit/places/jordan-hill-roman-temple/history/]; The precinct held deposits of ceramics [SUPPORTED: https://en.wikipedia.org/wiki/Jordan_Hill_Roman_Temple]; The precinct held deposits of coins [SUPPORTED: https://www.english-heritage.org.uk/visit/places/jordan-hill-roman-temple/history/]"}]'::jsonb),
    ('1876d7d8-2561-4f0b-8278-f89293aecbb7'::uuid, 'card_description', 'Lee Wood is the location of an Iron Age enclosure or hill fort situated near to Braunton and Barnstaple in Devon.', 'Cutting down the woods at Lee Wood in the 1960s partly uncovered a fireplace above Knowle Water: ashes and small pieces of animal bone, pig among them, dating from the Neolithic period.', 'teaser-card-s001:1876d7d8-2561-4f0b-8278-f89293aecbb7:card_description', 'teaser-card-s001 (teaser-card): teaser card, 185 characters, checked PASS, web-verified VERIFIED', '2a54af62567e55224abe20a38f5284969b839fe5edff4f192a8aaea1af5f9317|7c32bf76d628fa1074f75c649c76dc910b61b6cde8c3e0826bd04b90ddaef79f|7c32bf76d628fa1074f75c649c76dc910b61b6cde8c3e0826bd04b90ddaef79f', '[{"source": "lane WB run wb-pilot-2026-09-26c: writer teaser-write-001", "url": "output/remediation/teaser/runs/wb-pilot-2026-09-26c/OUTCOMES.jsonl", "quote": "Cutting down the woods at Lee Wood in the 1960s partly uncovered a fireplace above Knowle Water: ashes and small pieces of animal bone, pig among them, dating from the Neolithic period."}, {"source": "lane WB run wb-pilot-2026-09-26c: checker teaser-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-pilot-2026-09-26c/OUTCOMES.jsonl", "quote": "the woods at Lee Wood were cut down in the 1960s [S3]; that work partly uncovered a fireplace [S3]; the site (and so the fireplace) lies above Knowle Water [S2, S3]; the fireplace held ashes and small pieces of animal bone [S4]; pig was among the animal bone [S4]; the remains date from the Neolithic period [S4]"}, {"source": "lane WB run wb-pilot-2026-09-26c: verifier teaser-verify-001 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-pilot-2026-09-26c/OUTCOMES.jsonl", "quote": "Lee Wood is an archaeological site (an earthwork) above Knowle Water, England [SUPPORTED: https://en.wikipedia.org/wiki/Lee_Wood]; Woods at Lee Wood were cut down [SUPPORTED: https://en.wikipedia.org/wiki/Lee_Wood]; The woods were cut down in the 1960s [SUPPORTED: https://en.wikipedia.org/wiki/Lee_Wood]; The clearance partly uncovered a fireplace [SUPPORTED: https://en.wikipedia.org/wiki/Lee_Wood]; The fireplace contained ashes [SUPPORTED: https://en.wikipedia.org/wiki/Lee_Wood]; The fireplace contained small pieces of animal bone [SUPPORTED: https://en.wikipedia.org/wiki/Lee_Wood]; Pig bone was among the animal bones [SUPPORTED: https://en.wikipedia.org/wiki/Lee_Wood]; The finds date from the Neolithic period [SUPPORTED: https://en.wikipedia.org/wiki/Lee_Wood]"}]'::jsonb),
    ('26de5254-9e5e-4611-9439-35f3086d9ab5'::uuid, 'card_description', 'The tallest standing stones on the island, nearly 4 metres high. An 18th-century account described them as part of a ruinous circle of eight stones.', 'Once described as a ruinous circle of eight, the Bryn Gwyn Stones on Anglesey were torn up, says an account of 1797, by people supposing money was hid under them. A slab and a pillar remain.', 'teaser-card-s001:26de5254-9e5e-4611-9439-35f3086d9ab5:card_description', 'teaser-card-s001 (teaser-card): teaser card, 190 characters, checked PASS, web-verified VERIFIED', 'daa5f516232804c8bb8fb35b73101d6169d7149582c67992c2f9849d814560aa|6a593203a7d875059621e5ba418ab9ead24e843b3e7c905bac21605a5ee46af0|6a593203a7d875059621e5ba418ab9ead24e843b3e7c905bac21605a5ee46af0', '[{"source": "lane WB run wb-pilot-2026-09-26c: writer teaser-rewrite-v-001", "url": "output/remediation/teaser/runs/wb-pilot-2026-09-26c/OUTCOMES.jsonl", "quote": "Once described as a ruinous circle of eight, the Bryn Gwyn Stones on Anglesey were torn up, says an account of 1797, by people supposing money was hid under them. A slab and a pillar remain."}, {"source": "lane WB run wb-pilot-2026-09-26c: checker teaser-check-v-001 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-pilot-2026-09-26c/OUTCOMES.jsonl", "quote": "the Bryn Gwyn Stones are on Anglesey [S1, S2]; the stones were once described as a ruinous circle of eight [S4]; an account of 1797 says the stones were torn up [S5]; they were torn up by people supposing money was hid under them [S5]; a slab and a pillar remain [S5]"}, {"source": "lane WB run wb-pilot-2026-09-26c: verifier teaser-verify2-001 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-pilot-2026-09-26c/OUTCOMES.jsonl", "quote": "The Bryn Gwyn Stones are prehistoric standing stones on Anglesey [SUPPORTED: https://en.wikipedia.org/wiki/Bryn_Gwyn_stones]; Anglesey, where the stones stand, is in Wales [SUPPORTED: https://en.wikipedia.org/wiki/Bryn_Gwyn_stones]; The stones were once described as a ruinous circle of eight stones [SUPPORTED: https://en.wikipedia.org/wiki/Bryn_Gwyn_stones]; An account of 1797 says the stones were torn up [SUPPORTED: https://en.wikipedia.org/wiki/Bryn_Gwyn_stones]; According to that account, the stones were torn up by people supposing money was hid under them [SUPPORTED: https://en.wikipedia.org/wiki/Bryn_Gwyn_stones]; A slab remains [SUPPORTED: https://en.wikipedia.org/wiki/Bryn_Gwyn_stones]; A pillar remains [SUPPORTED: https://en.wikipedia.org/wiki/Bryn_Gwyn_stones]"}]'::jsonb),
    ('2753c6bb-1b90-4d49-8e59-b037bf1df930'::uuid, 'card_description', 'Flint tools found at the site give evidence of extensive traffic of Neanderthal populations in the area.', 'Neanderthals lived in Abrigo de la Quebrada, a rock shelter on a small ravine, only from June to October, and some of the flint they knapped there came from over 100 kilometers away.', 'teaser-card-s001:2753c6bb-1b90-4d49-8e59-b037bf1df930:card_description', 'teaser-card-s001 (teaser-card): teaser card, 182 characters, checked PASS, web-verified VERIFIED', 'ad3dc01d4156018dc8e97bb3257dc33d1da0fd86103c0caac91f025d2a81b155|1de628825be32de4b7b2efa125b75eaf8036f08ef5b95babd74a4032c5c2ea75|1de628825be32de4b7b2efa125b75eaf8036f08ef5b95babd74a4032c5c2ea75', '[{"source": "lane WB run wb-pilot-2026-09-26c: writer teaser-write-001", "url": "output/remediation/teaser/runs/wb-pilot-2026-09-26c/OUTCOMES.jsonl", "quote": "Neanderthals lived in Abrigo de la Quebrada, a rock shelter on a small ravine, only from June to October, and some of the flint they knapped there came from over 100 kilometers away."}, {"source": "lane WB run wb-pilot-2026-09-26c: checker teaser-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-pilot-2026-09-26c/OUTCOMES.jsonl", "quote": "Neanderthals occupied Abrigo de la Quebrada [S2]; it is a rock shelter [S3]; it lies on a small ravine [S3]; it was occupied only from June to October [S4]; flint was knapped at the site [S6, S7]; some of that flint came from over 100 kilometers away [S7]"}, {"source": "lane WB run wb-pilot-2026-09-26c: verifier teaser-verify-002 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-pilot-2026-09-26c/OUTCOMES.jsonl", "quote": "Abrigo de la Quebrada is a rock shelter on a small ravine [SUPPORTED: https://en.wikipedia.org/wiki/Abrigo_de_la_Quebrada]; The site is in Spain [SUPPORTED: https://en.wikipedia.org/wiki/Abrigo_de_la_Quebrada]; Neanderthals lived (occupied the shelter) there [SUPPORTED: https://en.wikipedia.org/wiki/Abrigo_de_la_Quebrada]; The shelter was occupied only from June to October [SUPPORTED: https://en.wikipedia.org/wiki/Abrigo_de_la_Quebrada]; Neanderthals knapped flint at the site [SUPPORTED: https://en.wikipedia.org/wiki/Abrigo_de_la_Quebrada]; Some of the flint came from over 100 kilometers away [SUPPORTED: https://en.wikipedia.org/wiki/Abrigo_de_la_Quebrada]"}]'::jsonb),
    ('4c5cee5c-42d5-443a-871a-730a8e584e89'::uuid, 'card_description', 'A multivallate hillfort on a triangular promontory, enclosed by a ditch 4 metres wide. Two spurs of a river valley provided natural defences on most sides.', 'Bury Camp, an Iron Age hillfort on a triangular promontory of Colerne Down, was built about 350 BC, yet the Neolithic and Mesolithic flint tools found there point to a much earlier use.', 'teaser-card-s001:4c5cee5c-42d5-443a-871a-730a8e584e89:card_description', 'teaser-card-s001 (teaser-card): teaser card, 185 characters, checked PASS, web-verified VERIFIED', 'dd986319ef0c9503d3be54cb7c25fddab195ffbbf35e2529694ad9c92ea16181|5f10b264da6ac6746b5d0edbcdf87fecd14aa18956bfd92f46f60a5d5790bcc6|5f10b264da6ac6746b5d0edbcdf87fecd14aa18956bfd92f46f60a5d5790bcc6', '[{"source": "lane WB run wb-pilot-2026-09-26c: writer teaser-write-001", "url": "output/remediation/teaser/runs/wb-pilot-2026-09-26c/OUTCOMES.jsonl", "quote": "Bury Camp, an Iron Age hillfort on a triangular promontory of Colerne Down, was built about 350 BC, yet the Neolithic and Mesolithic flint tools found there point to a much earlier use."}, {"source": "lane WB run wb-pilot-2026-09-26c: checker teaser-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-pilot-2026-09-26c/OUTCOMES.jsonl", "quote": "Bury Camp is an Iron Age hillfort [S1]; it sits on a triangular promontory of Colerne Down [S2]; it was built about 350 BC [S4]; Neolithic and Mesolithic flint tools were found there [S4]; those tools point to a much earlier use [S4]"}, {"source": "lane WB run wb-pilot-2026-09-26c: verifier teaser-verify-002 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-pilot-2026-09-26c/OUTCOMES.jsonl", "quote": "Bury Camp is an Iron Age hillfort (in England) [SUPPORTED: https://en.wikipedia.org/wiki/Bury_Camp]; It stands on a triangular promontory of Colerne Down [SUPPORTED: https://en.wikipedia.org/wiki/Bury_Camp]; The hillfort was built about 350 BC [SUPPORTED: https://en.wikipedia.org/wiki/Bury_Camp]; Neolithic and Mesolithic flint tools were found there [SUPPORTED: https://en.wikipedia.org/wiki/Bury_Camp]; The flint tools point to a much earlier use of the site [SUPPORTED: https://en.wikipedia.org/wiki/Bury_Camp]"}]'::jsonb),
    ('4f616866-4a3f-4754-9855-193df8e63fdc'::uuid, 'card_description', 'In 1995 a Roman temple building was discovered, which had been dedicated by the governor Dolabella and contained statues of the emperors Claudius and Vespasian.', 'In 1995 a Roman temple was found at Narona in the Neretva valley. Its statues of the emperors Claudius and Vespasian lay on the floor, vandalized in the 4th century, their heads broken off.', 'teaser-card-s001:4f616866-4a3f-4754-9855-193df8e63fdc:card_description', 'teaser-card-s001 (teaser-card): teaser card, 189 characters, checked PASS, web-verified VERIFIED', '3d3574ce13e239c7e97528968ca65b3e0d0b385c98dfa8a4647eb05c7b0837ad|5419032a384dae69d2d3e45fb8171ecf4ecb965a06b3774ea17b2c6cc88d8fb6|5419032a384dae69d2d3e45fb8171ecf4ecb965a06b3774ea17b2c6cc88d8fb6', '[{"source": "lane WB run wb-pilot-2026-09-26c: writer teaser-write-001", "url": "output/remediation/teaser/runs/wb-pilot-2026-09-26c/OUTCOMES.jsonl", "quote": "In 1995 a Roman temple was found at Narona in the Neretva valley. Its statues of the emperors Claudius and Vespasian lay on the floor, vandalized in the 4th century, their heads broken off."}, {"source": "lane WB run wb-pilot-2026-09-26c: checker teaser-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-pilot-2026-09-26c/OUTCOMES.jsonl", "quote": "a Roman temple was found at Narona in 1995 [S5]; Narona is in the Neretva valley [S1]; the temple held statues of the emperors Claudius and Vespasian [S5]; the statues lay on the floor [S6]; the statues were vandalized in the 4th century [S6]; the statues'' heads were broken off [S6]"}, {"source": "lane WB run wb-pilot-2026-09-26c: verifier teaser-verify-002 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-pilot-2026-09-26c/OUTCOMES.jsonl", "quote": "Narona is an ancient (Roman) city site in the Neretva valley, Croatia [SUPPORTED: https://en.wikipedia.org/wiki/Narona]; A Roman temple was found at Narona in 1995 [SUPPORTED: https://en.wikipedia.org/wiki/Narona]; The temple held statues of the emperors Claudius and Vespasian [SUPPORTED: https://en.wikipedia.org/wiki/Narona]; The statues lay on the floor [SUPPORTED: https://en.wikipedia.org/wiki/Narona]; The statues were vandalized in the 4th century [SUPPORTED: https://en.wikipedia.org/wiki/Narona]; The statues'' heads were broken off [SUPPORTED: https://museums.hr/en/museum/details/18332/arheoloski-muzej-narona]"}]'::jsonb),
    ('569f53de-6821-4597-b4f3-f695504b9d60'::uuid, 'card_description', 'The largest surviving fogou in Cornwall — an underground dry-stone passage from the Iron Age whose original purpose remains a mystery. Storage, shelter, or ritual? Nobody knows.', 'A long narrow tunnel roofed and walled in stone leads to three chambers: Halliggye Fogou, the largest and best-preserved of several mysterious tunnels linked to Cornish Iron Age settlements.', 'teaser-card-s001:569f53de-6821-4597-b4f3-f695504b9d60:card_description', 'teaser-card-s001 (teaser-card): teaser card, 190 characters, checked PASS, web-verified VERIFIED', '0991befb5f38a8ad673153fd0099de5f6a602d1dfae6712bf12417b4a9f3600a|54fb26db728fe32d2f66d55d11cd2b62133cac6e6f2e0b754121edf6783b099a|54fb26db728fe32d2f66d55d11cd2b62133cac6e6f2e0b754121edf6783b099a', '[{"source": "lane WB run wb-pilot-2026-09-26c: writer teaser-write-001", "url": "output/remediation/teaser/runs/wb-pilot-2026-09-26c/OUTCOMES.jsonl", "quote": "A long narrow tunnel roofed and walled in stone leads to three chambers: Halliggye Fogou, the largest and best-preserved of several mysterious tunnels linked to Cornish Iron Age settlements."}, {"source": "lane WB run wb-pilot-2026-09-26c: checker teaser-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-pilot-2026-09-26c/OUTCOMES.jsonl", "quote": "Halliggye Fogou has a long narrow tunnel [S2]; it is roofed and walled in stone [S3]; the tunnel leads to three chambers [S2]; it is the largest and best-preserved of several tunnels linked to Cornish Iron Age settlements [S3]; those tunnels are mysterious [S3]"}, {"source": "lane WB run wb-pilot-2026-09-26c: verifier teaser-verify-002 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-pilot-2026-09-26c/OUTCOMES.jsonl", "quote": "Halliggye Fogou is a fogou, an underground stone tunnel complex, in Cornwall, England [SUPPORTED: https://en.wikipedia.org/wiki/Halliggye_Fogou]; It consists of a long narrow tunnel [SUPPORTED: https://en.wikipedia.org/wiki/Halliggye_Fogou]; The tunnel is roofed and walled in stone [SUPPORTED: https://www.english-heritage.org.uk/visit/places/halliggye-fogou/]; The tunnel leads to three chambers [SUPPORTED: https://en.wikipedia.org/wiki/Halliggye_Fogou]; It is the largest and best-preserved of several such tunnels [SUPPORTED: https://www.english-heritage.org.uk/visit/places/halliggye-fogou/]; These tunnels are mysterious (their purpose is unknown) [SUPPORTED: https://www.english-heritage.org.uk/visit/places/halliggye-fogou/]; These tunnels are linked to Cornish Iron Age settlements [SUPPORTED: https://www.english-heritage.org.uk/visit/places/halliggye-fogou/]"}]'::jsonb),
    ('5e7bedef-ef5e-44b4-b479-ec462b3ba954'::uuid, 'card_description', 'An ancient Hohokam fortification atop a lava-capped mesa rising 305 metres above its base. Stone walls, petroglyphs, and pottery sherds mark the summit.', 'Atop Black Mountain, a lava capped mesa southwest of Tucson, lie the ruins of an ancient Hohokam fortification, where long stone walls, stone rings and petroglyphs can still be seen today.', 'teaser-card-s001:5e7bedef-ef5e-44b4-b479-ec462b3ba954:card_description', 'teaser-card-s001 (teaser-card): teaser card, 188 characters, checked PASS, web-verified VERIFIED', 'c758d82813771633c110a31901905dab15aff3f4b1ce73e64f945113d4f125f6|779e1e2d74e482f5252e49755d332d9df44d8a1de5d4eb036f88de6cec53d472|779e1e2d74e482f5252e49755d332d9df44d8a1de5d4eb036f88de6cec53d472', '[{"source": "lane WB run wb-pilot-2026-09-26c: writer teaser-write-001", "url": "output/remediation/teaser/runs/wb-pilot-2026-09-26c/OUTCOMES.jsonl", "quote": "Atop Black Mountain, a lava capped mesa southwest of Tucson, lie the ruins of an ancient Hohokam fortification, where long stone walls, stone rings and petroglyphs can still be seen today."}, {"source": "lane WB run wb-pilot-2026-09-26c: checker teaser-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-pilot-2026-09-26c/OUTCOMES.jsonl", "quote": "Black Mountain is a lava capped mesa [S1]; it lies southwest of Tucson [S2]; the ruins of an ancient Hohokam fortification lie on top of it [S5]; long stone walls can still be seen there today [S6]; stone rings can still be seen there today [S6]; petroglyphs can still be seen there today [S6]"}, {"source": "lane WB run wb-pilot-2026-09-26c: verifier teaser-verify-002 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-pilot-2026-09-26c/OUTCOMES.jsonl", "quote": "The ruins of an ancient Hohokam fortification lie atop Black Mountain (Pima County, Arizona, USA) [SUPPORTED: https://en.wikipedia.org/wiki/Black_Mountain_(Pima_County,_Arizona)]; Black Mountain is a lava