    ('7063f8dc-a347-4324-9930-6983ed9c997a'::uuid, 'card_description', 'A 2nd-century fire temple variously identified as Zoroastrian, solar, or Manichean. It was destroyed in the 5th century, and its true religious identity is still debated.', 'In Kakheti lie the foundations of the Nekresi Fire Temple, identified as a Zoroastrian fire temple, sun temple or Manichean shrine; charcoal suggests it was destroyed in the 5th century.', 'teaser-card-s001:7063f8dc-a347-4324-9930-6983ed9c997a:card_description', 'teaser-card-s001 (teaser-card): teaser card, 186 characters, checked PASS, web-verified VERIFIED', '2fac6f36d980ffbb1ef81233ac804edc324572d085d705359a669f271b273a43|4ca96b3709724de55b3dc3316b1d0d30fd977e097368487b37a0c30821bb4a66|4ca96b3709724de55b3dc3316b1d0d30fd977e097368487b37a0c30821bb4a66', '[{"source": "lane WB run wb-pilot-2026-09-26c: writer teaser-write-001", "url": "output/remediation/teaser/runs/wb-pilot-2026-09-26c/OUTCOMES.jsonl", "quote": "In Kakheti lie the foundations of the Nekresi Fire Temple, identified as a Zoroastrian fire temple, sun temple or Manichean shrine; charcoal suggests it was destroyed in the 5th century."}, {"source": "lane WB run wb-pilot-2026-09-26c: checker teaser-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-pilot-2026-09-26c/OUTCOMES.jsonl", "quote": "the Nekresi Fire Temple is in Kakheti [S1]; only its foundations remain [S2]; it is identified as a Zoroastrian fire temple, sun temple or Manichean shrine [S2]; charcoal suggests it was destroyed in the 5th century [S4]"}, {"source": "lane WB run wb-pilot-2026-09-26c: verifier teaser-verify-003 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-pilot-2026-09-26c/OUTCOMES.jsonl", "quote": "The Nekresi Fire Temple is an archaeological temple complex in the Kakheti region of Georgia [SUPPORTED: https://en.wikipedia.org/wiki/Nekresi_fire_temple]; Only its foundations survive [SUPPORTED: https://en.wikipedia.org/wiki/Nekresi_fire_temple]; It has been identified as a Zoroastrian fire temple [SUPPORTED: https://en.wikipedia.org/wiki/Nekresi_fire_temple]; It has alternatively been identified as a sun temple [SUPPORTED: https://en.wikipedia.org/wiki/Nekresi_fire_temple]; It has alternatively been identified as a Manichean shrine [SUPPORTED: https://en.wikipedia.org/wiki/Nekresi_fire_temple]; Charcoal suggests it was destroyed in the 5th century [SUPPORTED: https://en.wikipedia.org/wiki/Nekresi_fire_temple]"}]'::jsonb),
    ('85a15fe0-fbb8-4072-b73a-7345fbe6f9dc'::uuid, 'card_description', NULL, 'On the South Downs, a shaft at Harrow Hill excavated in 1924–25 proved 6.7 metres deep, with some exploitation of the upper flint levels and six radiating galleries at the bottom of the pit.', 'teaser-card-s001:85a15fe0-fbb8-4072-b73a-7345fbe6f9dc:card_description', 'teaser-card-s001 (teaser-card): teaser card, 190 characters, checked PASS, web-verified VERIFIED', '732b69abc538db06f0d3c53fe926cb0c07ac69a1e21a9221c35a1b30b5b20caf|72648d106d1c4fac4b6ca8450361365b6867df76f8543904b62c95f2f09a5653|72648d106d1c4fac4b6ca8450361365b6867df76f8543904b62c95f2f09a5653', '[{"source": "lane WB run wb-pilot-2026-09-26c: writer teaser-write-001", "url": "output/remediation/teaser/runs/wb-pilot-2026-09-26c/OUTCOMES.jsonl", "quote": "On the South Downs, a shaft at Harrow Hill excavated in 1924–25 proved 6.7 metres deep, with some exploitation of the upper flint levels and six radiating galleries at the bottom of the pit."}, {"source": "lane WB run wb-pilot-2026-09-26c: checker teaser-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-pilot-2026-09-26c/OUTCOMES.jsonl", "quote": "Harrow Hill is on the South Downs [S2]; a shaft there was excavated in 1924-25 [S3]; the shaft proved 6.7 metres deep [S3]; there had been some exploitation of the upper flint levels [S4]; there were six radiating galleries at the bottom of the pit [S4]"}, {"source": "lane WB run wb-pilot-2026-09-26c: verifier teaser-verify-003 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-pilot-2026-09-26c/OUTCOMES.jsonl", "quote": "Harrow Hill is the site of a Neolithic flint mine [SUPPORTED: https://en.wikipedia.org/wiki/Harrow_Hill,_West_Sussex]; Harrow Hill is on the South Downs [SUPPORTED: https://en.wikipedia.org/wiki/Harrow_Hill,_West_Sussex]; A shaft at Harrow Hill was excavated in 1924-25 [SUPPORTED: https://en.wikipedia.org/wiki/Harrow_Hill,_West_Sussex]; The excavated shaft proved 6.7 metres deep [SUPPORTED: https://en.wikipedia.org/wiki/Harrow_Hill,_West_Sussex]; There had been some exploitation of the upper flint levels [SUPPORTED: https://en.wikipedia.org/wiki/Harrow_Hill,_West_Sussex]; Six radiating galleries lay at the bottom of the pit [SUPPORTED: https://en.wikipedia.org/wiki/Harrow_Hill,_West_Sussex]"}]'::jsonb),
    ('8c624c02-31b5-4058-8551-f7cec08e6359'::uuid, 'card_description', 'Radiocarbon dates place the principal occupation of the site in the early to mid-fifth millennium BC.', 'Bülövqaya, a Chalcolithic settlement on the Sarısu River, yielded painted pottery, hearths and pottery kilns, and in its analysed obsidian, material from the Zangezur Mountains predominated.', 'teaser-card-s001:8c624c02-31b5-4058-8551-f7cec08e6359:card_description', 'teaser-card-s001 (teaser-card): teaser card, 190 characters, checked PASS, web-verified VERIFIED', '69ca1e04f9013c5a3ce84a49076b1a72581377c6437ad0e80439f95cafc9dca9|0ee6e45641c7bb3383514cfe62e1c5c15a978a421cd042dcee2da2c27a264c8c|0ee6e45641c7bb3383514cfe62e1c5c15a978a421cd042dcee2da2c27a264c8c', '[{"source": "lane WB run wb-pilot-2026-09-26c: writer teaser-write-001", "url": "output/remediation/teaser/runs/wb-pilot-2026-09-26c/OUTCOMES.jsonl", "quote": "Bülövqaya, a Chalcolithic settlement on the Sarısu River, yielded painted pottery, hearths and pottery kilns, and in its analysed obsidian, material from the Zangezur Mountains predominated."}, {"source": "lane WB run wb-pilot-2026-09-26c: checker teaser-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-pilot-2026-09-26c/OUTCOMES.jsonl", "quote": "Bülövqaya is a Chalcolithic settlement [S1]; it lies on the Sarısu River [S2]; it yielded painted pottery [S4]; it yielded hearths [S4]; it yielded pottery kilns [S4]; its obsidian was analysed [S6]; material from the Zangezur Mountains predominated in that obsidian [S6]"}, {"source": "lane WB run wb-pilot-2026-09-26c: verifier teaser-verify-003 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-pilot-2026-09-26c/OUTCOMES.jsonl", "quote": "Bülövqaya is a Chalcolithic settlement [SUPPORTED: https://en.wikipedia.org/wiki/B%C3%BCl%C3%B6vqaya]; Bülövqaya lies on the Sarısu River [SUPPORTED: https://en.wikipedia.org/wiki/B%C3%BCl%C3%B6vqaya]; The site yielded painted pottery [SUPPORTED: https://en.wikipedia.org/wiki/B%C3%BCl%C3%B6vqaya]; The site yielded hearths [SUPPORTED: https://en.wikipedia.org/wiki/B%C3%BCl%C3%B6vqaya]; The site yielded pottery kilns [SUPPORTED: https://en.wikipedia.org/wiki/B%C3%BCl%C3%B6vqaya]; Obsidian from the site has been analysed for its source [SUPPORTED: https://en.wikipedia.org/wiki/B%C3%BCl%C3%B6vqaya]; In the analysed obsidian, material from the Zangezur Mountains predominated [SUPPORTED: https://en.wikipedia.org/wiki/B%C3%BCl%C3%B6vqaya]"}]'::jsonb),
    ('9d65d8dd-ef7f-4479-ad2b-1fde36484e23'::uuid, 'card_description', 'The Tegeatae are said to have derived their name from Tegeates, a son of Lycaon, and to have dwelt originally in eight, afterwards nine, demoi or townships.', 'Mount Parthenium parted Argolis from the land of Tegea, one of the most ancient and powerful towns of Arcadia, its people said to take their name from Tegeates, a son of Lycaon.', 'teaser-card-s001:9d65d8dd-ef7f-4479-ad2b-1fde36484e23:card_description', 'teaser-card-s001 (teaser-card): teaser card, 177 characters, checked PASS, web-verified VERIFIED', '26a116de578d5c95503a63cd4f63bcef8b432f1c65457947c77c65d3e209aed0|4e4d4297da919c0633338807ad76ec99665658e033a900ef75e2c7cb3546a380|4e4d4297da919c0633338807ad76ec99665658e033a900ef75e2c7cb3546a380', '[{"source": "lane WB run wb-pilot-2026-09-26c: writer teaser-write-002", "url": "output/remediation/teaser/runs/wb-pilot-2026-09-26c/OUTCOMES.jsonl", "quote": "Mount Parthenium parted Argolis from the land of Tegea, one of the most ancient and powerful towns of Arcadia, its people said to take their name from Tegeates, a son of Lycaon."}, {"source": "lane WB run wb-pilot-2026-09-26c: checker teaser-check-002 (check), PASS", "url": "output/remediation/teaser/runs/wb-pilot-2026-09-26c/OUTCOMES.jsonl", "quote": "Mount Parthenium separated Argolis from the territory of Tegea [S2]; Tegea was one of the most ancient towns of Arcadia [S1]; Tegea was one of the most powerful towns of Arcadia [S1]; its people are said to take their name from Tegeates [S3]; Tegeates was a son of Lycaon [S3]"}, {"source": "lane WB run wb-pilot-2026-09-26c: verifier teaser-verify-004 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-pilot-2026-09-26c/OUTCOMES.jsonl", "quote": "Tegea was an ancient town (settlement) in Arcadia, Greece [SUPPORTED: https://en.wikipedia.org/wiki/Tegea]; Mount Parthenium separated Argolis from the territory of Tegea [SUPPORTED: https://en.wikipedia.org/wiki/Tegea]; Tegea was one of the most ancient towns of Arcadia [SUPPORTED: https://en.wikipedia.org/wiki/Tegea]; Tegea was one of the most powerful towns of Arcadia [SUPPORTED: https://en.wikipedia.org/wiki/Tegea]; The people of Tegea were said to take their name from Tegeates [SUPPORTED: https://en.wikipedia.org/wiki/Tegea]; Tegeates was a son of Lycaon [SUPPORTED: https://en.wikipedia.org/wiki/Tegeates]"}]'::jsonb),
    ('b2035589-d46f-496f-9736-15d2251bca4a'::uuid, 'card_description', 'Capital of the Kowoj Maya, built across three islands in a lake. Occupied from 350 BC to 1200 AD, the largest Postclassic site in the Peten Basin.', 'On Isla Principal Topoxte in Yaxha Lake lie the ruins of around 100 structures and the ceremonial centre of the Kowoj Maya capital, abandoned circa 900 and reoccupied approximately 1100.', 'teaser-card-s001:b2035589-d46f-496f-9736-15d2251bca4a:card_description', 'teaser-card-s001 (teaser-card): teaser card, 186 characters, checked PASS, web-verified VERIFIED', 'c4859c158c4fa908f13824427b8e36fd5935482450e6053c76c6e00931d6672a|e0021f024ee47288c9390fd68d3d71bd44fd132f522066919bd4e222c9bdf6a5|e0021f024ee47288c9390fd68d3d71bd44fd132f522066919bd4e222c9bdf6a5', '[{"source": "lane WB run wb-pilot-2026-09-26c: writer teaser-write-002", "url": "output/remediation/teaser/runs/wb-pilot-2026-09-26c/OUTCOMES.jsonl", "quote": "On Isla Principal Topoxte in Yaxha Lake lie the ruins of around 100 structures and the ceremonial centre of the Kowoj Maya capital, abandoned circa 900 and reoccupied approximately 1100."}, {"source": "lane WB run wb-pilot-2026-09-26c: checker teaser-check-002 (check), PASS", "url": "output/remediation/teaser/runs/wb-pilot-2026-09-26c/OUTCOMES.jsonl", "quote": "Isla Principal Topoxte lies in Yaxha Lake [S5]; the island holds the remains of around 100 structures [S7]; the island holds the ceremonial centre of the city [S7]; the city was the capital of the Kowoj Maya [S2]; the site was abandoned circa 900 [S3]; the site was reoccupied approximately 1100 [S3]"}, {"source": "lane WB run wb-pilot-2026-09-26c: verifier teaser-verify-004 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-pilot-2026-09-26c/OUTCOMES.jsonl", "quote": "Isla Principal Topoxte is an island in Yaxha Lake, Guatemala, bearing the ruins of a Maya city [SUPPORTED: https://en.wikipedia.org/wiki/Topoxte]; Topoxte is a Maya archaeological site in Guatemala [SUPPORTED: https://en.wikipedia.org/wiki/Topoxte]; Topoxte Island holds the ruins of around 100 structures [SUPPORTED: https://en.wikipedia.org/wiki/Topoxte]; Topoxte Island holds the ceremonial centre of the city [SUPPORTED: https://en.wikipedia.org/wiki/Topoxte]; Topoxte was the capital of the Kowoj Maya [SUPPORTED: https://en.wikipedia.org/wiki/Topoxte]; The site was abandoned circa 900 [SUPPORTED: https://en.wikipedia.org/wiki/Topoxte]; The site was reoccupied approximately 1100 [SUPPORTED: https://en.wikipedia.org/wiki/Topoxte]"}]'::jsonb),
    ('c1eb720c-5523-4f48-8fed-ca7aa0199e54'::uuid, 'card_description', 'Excavation first began in 1968, by which time the "large structure with its great Ionic columns set on a high stone platform" had been associated with a comment by Isidore of Charax.', 'Great Ionic columns on a high stone platform at Kangavar: the Anahita Temple, tied to a temple of Artemis mentioned by Isidore of Charax, though scholars dispute what its main structure was.', 'teaser-card-s001:c1eb720c-5523-4f48-8fed-ca7aa0199e54:card_description', 'teaser-card-s001 (teaser-card): teaser card, 190 characters, checked PASS, web-verified VERIFIED', 'c8c8afb67f241bde67574146ec695057ba33739eedb129419e3180024d4d3a90|dd5c4a1fede650553f5fb1e31907fd0baf906d1a457ce8b6e9c526694f2e2c7e|dd5c4a1fede650553f5fb1e31907fd0baf906d1a457ce8b6e9c526694f2e2c7e', '[{"source": "lane WB run wb-pilot-2026-09-26c: writer teaser-write-002", "url": "output/remediation/teaser/runs/wb-pilot-2026-09-26c/OUTCOMES.jsonl", "quote": "Great Ionic columns on a high stone platform at Kangavar: the Anahita Temple, tied to a temple of Artemis mentioned by Isidore of Charax, though scholars dispute what its main structure was."}, {"source": "lane WB run wb-pilot-2026-09-26c: checker teaser-check-002 (check), PASS", "url": "output/remediation/teaser/runs/wb-pilot-2026-09-26c/OUTCOMES.jsonl", "quote": "the site has great Ionic columns set on a high stone platform [S5]; the site is at Kangavar [S2]; the site is called the Anahita Temple [S1, S2]; the structure has been associated with a temple of Artemis mentioned by Isidore of Charax [S5]; scholars dispute the identity of the main structure (a stated uncertainty) [S4]"}, {"source": "lane WB run wb-pilot-2026-09-26c: verifier teaser-verify-004 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-pilot-2026-09-26c/OUTCOMES.jsonl", "quote": "The Anahita Temple is an archaeological site at Kangavar, Iran, popularly held to be a temple of Anahita [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Anahita,_Kangavar]; The site is popularly attributed to the Iranian deity Anahita [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Anahita,_Kangavar]; The structure has great Ionic columns [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Anahita,_Kangavar]; The columns stand on a high stone platform [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Anahita,_Kangavar]; The site has been tied to a comment by Isidore of Charax [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Anahita,_Kangavar]; Isidore of Charax mentioned a temple of Artemis, which has been tied to the Anahita Temple [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Anahita,_Kangavar]; Scholars dispute what the main structure of the site was [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Anahita,_Kangavar]"}]'::jsonb),
    ('ee0017b2-44f4-426d-8901-5842c832eb30'::uuid, 'card_description', 'Dubbed the most Roman city outside Italy, it has the best-preserved Roman arena and the Maison Carree temple. Neolithic habitation dates to 4000 BC.', NULL, 'teaser-card-s001:ee0017b2-44f4-426d-8901-5842c832eb30:card_description', 'teaser-card-s001 (card-clear-contradicted-after-verify): card cleared (contradicted-after-verify)', '||389d09d376bf6568d3fdde1bbe11c0979155b377c4e50db6827198a5291cdfc8', '[{"source": "lane WB run wb-pilot-2026-09-26c: contradicted-after-verify", "url": "output/remediation/teaser/runs/wb-pilot-2026-09-26c/OUTCOMES.jsonl", "quote": "The web check contradicts: The Maison Carrée is a small temple (https://en.wikipedia.org/wiki/Maison_carr%C3%A9e: \"It is a mid-sized Augustan provincial temple\"); The web check contradicts: The Maison Carrée was built circa 19 BCE (https://fr.wikipedia.org/wiki/Maison_carr%C3%A9e: \"Cet édifice a été bâti entre 10 av. J.-C. et 4 apr. J.-C.\"); The web check contradicts: The Augustan ramparts had 14 towers (https://nimes-tourisme.com/en/explorer/nimes/monuments-et-sites/lenceinte-romaine/: \"with a dozen gates and some 80 towers, including the Tour Magne\")"}]'::jsonb),
    ('fa579d23-36bc-469f-9351-2be5f11e180f'::uuid, 'card_description', 'A Gandharan village near Rawalpindi dating to roughly 2,000 years ago, known for the nearby Manikyala Stupa. Local tradition holds the Buddha sacrificed part of his body here to feed seven tiger cubs.', 'Mankiala''s stupa marks where, legend says, an earlier incarnation of Buddha fed seven hungry tiger cubs with part or all of his body. Relics were found 10 to 20 metres below its dome top.', 'teaser-card-s001:fa579d23-36bc-469f-9351-2be5f11e180f:card_description', 'teaser-card-s001 (teaser-card): teaser card, 187 characters, checked PASS, web-verified VERIFIED', 'fb83b099d75ece1c7c7c325e05b429b8c79b8bf06a497cf4bf33b9094b508d33|4d2c9508c3ac93c7e13d9a89be3bdb40d5db96b97eb11afa2014cca62c357432|4d2c9508c3ac93c7e13d9a89be3bdb40d5db96b97eb11afa2014cca62c357432', '[{"source": "lane WB run wb-pilot-2026-09-26c: writer teaser-write-002", "url": "output/remediation/teaser/runs/wb-pilot-2026-09-26c/OUTCOMES.jsonl", "quote": "Mankiala''s stupa marks where, legend says, an earlier incarnation of Buddha fed seven hungry tiger cubs with part or all of his body. Relics were found 10 to 20 metres below its dome top."}, {"source": "lane WB run wb-pilot-2026-09-26c: checker teaser-check-002 (check), PASS", "url": "output/remediation/teaser/runs/wb-pilot-2026-09-26c/OUTCOMES.jsonl", "quote": "Mankiala''s stupa memorializes the place of a legend [S1]; according to legend, an earlier incarnation of Buddha fed seven hungry tiger cubs [S1]; according to legend, he fed them with part or all of his body [S1]; relics were found between 10 and 20 metres below the top of the stupa''s dome [S5, S6]"}, {"source": "lane WB run wb-pilot-2026-09-26c: verifier teaser-verify-004 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-pilot-2026-09-26c/OUTCOMES.jsonl", "quote": "Mankiala is the site of a Buddhist stupa in Pakistan [SUPPORTED: https://en.wikipedia.org/wiki/Manikyala_Stupa]; Mankiala is in Pakistan [SUPPORTED: https://en.wikipedia.org/wiki/Mankiala]; According to legend, the stupa marks the place where an earlier incarnation of the Buddha fed hungry tiger cubs [SUPPORTED: https://en.wikipedia.org/wiki/Mankiala]; There were seven tiger cubs [SUPPORTED: https://en.wikipedia.org/wiki/Manikyala_Stupa]; He fed them with part or all of his body [SUPPORTED: https://en.wikipedia.org/wiki/Mankiala]; Relics were found in the stupa [SUPPORTED: https://en.wikipedia.org/wiki/Mankiala]; The relics were found 10 to 20 metres below the top of the dome [SUPPORTED: https://en.wikipedia.org/wiki/Mankiala]"}]'::jsonb);

DO $$
DECLARE
    bad      INTEGER;
    moved    INTEGER := 0;
    expected INTEGER := 20;
    r        RECORD;
BEGIN
    -- expected is the plan's own row count, rendered here, and not a second count of the
    -- temp table the loop below iterates: counting the same table twice would make the
    -- comparison after the loop a tautology. The instance that makes a short loop
    -- unreachable is apply_remediation_change, which raises unless exactly one row
    -- matched; this guard is what reports a loop that changed fewer rows than the plan.

    -- scope guard 1: every planned row is a card_stats row of a curated site that still exists
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p LEFT JOIN card_stats t ON t.site_id = p.site_id
      LEFT JOIN unified_sites u ON u.id = p.site_id
     WHERE t.site_id IS NULL OR u.id IS NULL OR u.source_id <> 'ancient_nerds';
    IF bad > 0 THEN
        -- the source name is a RAISE argument, never part of the quoted message: a name
        -- spliced into the message text only parses while the name happens to contain no
        -- quote, which is a property of today's value and not of this code. G0's guard is
        -- the shape this one copies.
        RAISE EXCEPTION 'teaser card: % planned row(s) are not % sites', bad, 'ancient_nerds';
    END IF;

    -- scope guard 2: the plan is a set of real changes, each one writable in its column
    -- (compared in the column's own type; CASE, because only CASE fixes the order in
    -- which the casts are evaluated)
    SELECT count(*) INTO bad FROM _teaser_card_plan p
     WHERE p.new_value = '' OR CASE p.column_name
                WHEN 'card_description' THEN p.new_value::character varying IS NOT DISTINCT FROM p.old_value::character varying OR length(p.new_value) > 200
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) are not writable changes', bad;
    END IF;

    -- scope guard 3: every planned row still holds the old value the plan names
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p JOIN card_stats t ON t.site_id = p.site_id
     WHERE CASE p.column_name
                WHEN 'card_description' THEN t.card_description IS DISTINCT FROM p.old_value::character varying
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) no longer hold the planned old value', bad;
    END IF;

    -- scope guard 5: every planned row still holds the input its value was derived from
    SELECT count(*) INTO bad
      FROM (SELECT DISTINCT site_id, premise FROM _teaser_card_plan) p JOIN unified_sites u ON u.id = p.site_id
     WHERE (coalesce(u.raw_data -> '_card_provenance' ->> 'text_sha256', '') || '|' || coalesce(u.raw_data -> '_card_provenance' ->> 'desc_sha256', '') || '|' || encode(sha256(convert_to(coalesce(u.description, ''), 'UTF8')), 'hex')) IS DISTINCT FROM p.premise;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) no longer hold the premise the plan derived its value from', bad;
    END IF;

    -- the only writer: the conditional UPDATE and its journal row commit together, and
    -- the function raises unless exactly one row matched
    FOR r IN SELECT * FROM _teaser_card_plan ORDER BY site_id, column_name LOOP
        moved := moved + apply_remediation_change(
            'card_stats', r.column_name, 'site_id', r.site_id::text,
            r.old_value, r.new_value,
            'WB/teaser-card', 'wb-teaser-card-s001', r.change_key, 'opus-checked', r.evidence, r.site_id);
    END LOOP;

    IF moved <> expected THEN
        RAISE EXCEPTION 'teaser card: % row(s) changed, % planned', moved, expected;
    END IF;

    -- invariant 1: every planned row now holds the new value
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p JOIN card_stats t ON t.site_id = p.site_id
     WHERE CASE p.column_name
                WHEN 'card_description' THEN t.card_description IS DISTINCT FROM p.new_value::character varying
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) do not hold the new value', bad;
    END IF;

    -- invariant 2: the journal and the data agree, row for row, in both directions
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p LEFT JOIN remediation_change_log l
        ON l.row_pk = p.site_id::text AND l.table_name = 'card_stats'
       AND l.column_name = p.column_name
       AND l.run_stamp = 'wb-teaser-card-s001'
     WHERE l.id IS NULL
        OR l.new_value IS DISTINCT FROM p.new_value
        OR l.old_value IS DISTINCT FROM p.old_value;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) have no matching journal row', bad;
    END IF;

    SELECT count(*) INTO bad FROM remediation_change_log l
     WHERE l.run_stamp = 'wb-teaser-card-s001'
       AND (l.table_name <> 'card_stats' OR l.column_name NOT IN ('card_description'));
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: this run stamp journalled % row(s) outside card_stats.(card_description)', bad;
    END IF;

    RAISE NOTICE 'teaser card: % of % planned cell(s) changed and journalled over 20 curated site(s)',
        moved, expected;
END $$;

COMMIT;

-- Post-commit read: the numbers the report quotes, from the database, not from the plan.
SELECT 'journal rows for this run stamp' AS metric, count(*)::text AS value
  FROM remediation_change_log WHERE run_stamp = 'wb-teaser-card-s001'
UNION ALL
SELECT 'journal rows for this test id', count(*)::text
  FROM remediation_change_log WHERE test_id = 'WB/teaser-card'
UNION ALL
SELECT 'planned rows now holding the new value', count(*)::text
  FROM remediation_change_log l
 WHERE l.run_stamp = 'wb-teaser-card-s001' AND l.table_name = 'card_stats'
   AND l.column_name IN ('card_description')
   AND EXISTS (SELECT 1 FROM card_stats t
                WHERE t.site_id::text = l.row_pk AND CASE l.column_name
                WHEN 'card_description' THEN t.card_description IS NOT DISTINCT FROM l.new_value::character varying
                ELSE false END)
UNION ALL
SELECT 'curated sites whose teaser provenance does not hash their live card', count(*)::text
  FROM unified_sites
 WHERE source_id = 'ancient_nerds' AND raw_data ? '_card_provenance' AND NOT EXISTS (SELECT 1 FROM card_stats cs WHERE cs.site_id = unified_sites.id AND encode(sha256(convert_to(cs.card_description, 'UTF8')), 'hex') = unified_sites.raw_data -> '_card_provenance' ->> 'text_sha256')
UNION ALL
SELECT 'curated sites', count(*)::text
  FROM unified_sites WHERE source_id = 'ancient_nerds';
